class Solution {
public:
    int divide(int dividend, int divisor) {
        if (dividend == INT_MIN && divisor == -1) return INT_MAX;
        bool negative = (dividend < 0) ^ (divisor < 0);
        long long a = std::abs((long long)dividend);
        long long b = std::abs((long long)divisor);
        long long quotient = 0;
        for (int i = 31; i >= 0; i--) {
            if ((a >> i) >= b) {
                quotient += (1LL << i);
                a -= (b << i);
            }
        }
        long long res = negative ? -quotient : quotient;
        if (res > INT_MAX) return INT_MAX;
        if (res < INT_MIN) return INT_MIN;
        return (int)res;
    }
};

class Solution {
    public int divide(int dividend, int divisor) {
        if (dividend == Integer.MIN_VALUE && divisor == -1) return Integer.MAX_VALUE;
        boolean negative = (dividend < 0) ^ (divisor < 0);
        long a = Math.abs((long) dividend);
        long b = Math.abs((long) divisor);
        long quotient = 0;
        for (int i = 31; i >= 0; i--) {
            if ((a >> i) >= b) {
                quotient += (1L << i);
                a -= (b << i);
            }
        }
        long res = negative ? -quotient : quotient;
        if (res > Integer.MAX_VALUE) return Integer.MAX_VALUE;
        if (res < Integer.MIN_VALUE) return Integer.MIN_VALUE;
        return (int) res;
    }
}

var divide = function(dividend, divisor) {
    const INT_MAX = 2147483647;
    const INT_MIN = -2147483648;
    if (dividend === INT_MIN && divisor === -1) return INT_MAX;
    const negative = (dividend < 0) !== (divisor < 0);
    let a = Math.abs(dividend);
    const b = Math.abs(divisor);
    let quotient = 0;
    for (let i = 31; i >= 0; i--) {
        if ((a / Math.pow(2, i)) >= b) {
            quotient += Math.pow(2, i);
            a -= b * Math.pow(2, i);
        }
    }
    const res = negative ? -quotient : quotient;
    return Math.min(Math.max(res, INT_MIN), INT_MAX);
};
